   ```
   {
   ...
     "deschedulerPolicy": {
       "profiles": [
         {
           "name": "ProfileName",
           "pluginConfig": [
             {
               "args": {
                 "ignorePvcPods": true,
                 "nodeFit": true,
                 "priorityThreshold": {
                   "value": 100
                 }
               },
               "name": "DefaultEvictor"
             },
             {
               "args": {
                 "evictableNamespaces": {
                   "exclude": ["kube-system"]
                 },
                 "thresholds": {
                   "cpu": 25,
                   "memory": 25
                 }
               },
               "name": "HighNodeUtilization"
             }
           ],
           "plugins": {
             "balance": {
               "enabled": ["HighNodeUtilization"]
             }
           }
         }
       ]
     },
     "descheduler_enable": "true",
     "deschedulingInterval": "10m"
   ...
   }
   ```

